        address currentPool = AaveIPoolAddressProvider(poolAddressProvider).getPool(); 
        require(currentPool != address(0), "DR: invalid Aave pool address"); 
        require(currentPool != aavePool, "DR: new pool must be different"); 
        // Revoke approval for the old pool 
        IERC20(token).safeApprove(aavePool, 0); 
        // Set new pool address 
        aavePool = currentPool; 
        // Approve new pool 
        IERC20(token).safeApprove(aavePool, type(uint256).max); 
        emit AavePoolSet(currentPool); 
    }

